function InvestMainThankChooseGift:SaveFirstPayData()
    xRecord.record('3-009')
    local time = os.time()
    local t = timestamp_to_time(time)
    CfUtils.WriteLocalData("BtnFirstFlushClickTime", checkNumber(t.day))
    CfUtils.WriteLocalData("BtnFirstFlushIsFirstOpen", 1)
end

function InvestMainThankChooseGift:LoadRes()
    local loader = ResourceModule.LoadBundleSync("Timeline/Prefab/GiftfirstTLPack.prefab", nil, true)
    if loader.IsSuccess then
        table.insert(self.loaderList, loader)
        ---@type UnityEngine.GameObject
        local go = GameObject.Instantiate(loader.ResultObject)
        go.transform.localPosition = Vector3.New(-4, -0.2, 12)
        go.transform.localRotation = Quaternion.Euler(0, 62, 0)
        for i = 1, 3 do
            if i == 2 then
                self.timeLineGoList["2_1"] = go.transform:Find("2_1")
                self.timeLineGoList["2_2"] = go.transform:Find("2_2")
            else
                self.timeLineGoList[tostring(i)] = go.transform:Find(i)
            end
        end
    else
        loader:Release(true)
    end
end

function InvestMainThankChooseGift:isMultipleRewards()
    return table.count(self.data.frontRewards) > 1
end

function InvestMainThankChooseGift:HasWords()
    return not(string.isEmpty(self.data.textGift) or self.data.textGift == "")
end

function InvestMainThankChooseGift:HasSound()
    return false
end

