function InvestMainThankChooseGift:DisposeLoadRes()
    for k, v in pairs(self.loaderList) do
        if not isNull(v) then
            v:Release(true)
        end
    end
    for k, v in pairs(self.coList) do
        if not isNull(v) then
            cs_coroutine.stop(v)
        end
    end

    for k, v in pairs(self.timeLineGoList) do
        if not isNull(v) then
            GameObject.DestroyImmediate(v.transform.parent.gameObject)
            break
        end
    end
end

function InvestMainThankChooseGift:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        FeatureSignComponent.isInFeatureSign = false
        --Events.Broadcast(Constants.EventNames.MainHomeRoleActive, { isShow = true })

        if self.playedVoice then
            CriSoundMgr.Stop(self.playedVoice.CueInfo)
        end
        self:DisposeLoadRes()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return InvestMainThankChooseGift